mod common { include!("../common.rs"); }
use common::*;
use std::collections::HashMap;
fn main() { let (input, out_path) = read_input(); let output = handle(&input); write_output(&output, &out_path); }
fn handle(input: &WasmInput) -> WasmOutput {
    match (input.request.method.as_str(), input.endpoint.as_str()) {
        ("POST", "trips") => { let body: serde_json::Value = input.request.body.as_deref().and_then(|b| serde_json::from_str(b).ok()).unwrap_or_default(); let mut fields = HashMap::new(); fields.insert("system:node_title".into(), field_value("String", body["title"].as_str().unwrap_or("Untitled"))); if let Some(d) = body["start_date"].as_str() { fields.insert("trips:start_date".into(), field_value("DateTime", d)); } if let Some(d) = body["end_date"].as_str() { fields.insert("trips:end_date".into(), field_value("DateTime", d)); } let mut out = json_ok(serde_json::json!({"created":true})); out.effects.push(create_effect(fields)); out }
        ("GET", "trips") => { let trips: Vec<&WasmNode> = input.nodes.iter().filter(|n| n.fields.contains_key("trips:start_date")).collect(); json_ok(serde_json::json!(trips)) }
        ("POST", "events") => { let body: serde_json::Value = input.request.body.as_deref().and_then(|b| serde_json::from_str(b).ok()).unwrap_or_default(); let mut fields = HashMap::new(); fields.insert("system:node_title".into(), field_value("String", body["title"].as_str().unwrap_or("Untitled"))); if let Some(v) = body["start_time"].as_str() { fields.insert("system:node_start_time".into(), field_value("DateTime", v)); } if let Some(v) = body["trip_id"].as_str() { fields.insert("trips:trip_id".into(), field_value("String", v)); } if let Some(v) = body["latitude"].as_f64() { fields.insert("trips:latitude".into(), field_value("Float", v)); } if let Some(v) = body["longitude"].as_f64() { fields.insert("trips:longitude".into(), field_value("Float", v)); } if let Some(v) = body["location_name"].as_str() { fields.insert("trips:location_name".into(), field_value("String", v)); } let mut out = json_ok(serde_json::json!({"created":true})); out.effects.push(create_effect(fields)); out }
        ("GET", "events") => { let tid = input.request.query_params.get("trip_id"); let mut events: Vec<&WasmNode> = input.nodes.iter().filter(|n| n.fields.contains_key("trips:trip_id")).collect(); if let Some(t) = tid { events.retain(|n| n.fields.get("trips:trip_id").and_then(|v| v["value"].as_str()) == Some(t)); } json_ok(serde_json::json!(events)) }
        ("GET", "events/map") => { let map: Vec<serde_json::Value> = input.nodes.iter().filter(|n| n.fields.contains_key("trips:latitude") && n.fields.contains_key("trips:longitude")).map(|n| serde_json::json!({"id": n.id, "title": n.fields.get("system:node_title").and_then(|v| v["value"].as_str()).unwrap_or(""), "latitude": n.fields.get("trips:latitude").and_then(|v| v["value"].as_f64()).unwrap_or(0.0), "longitude": n.fields.get("trips:longitude").and_then(|v| v["value"].as_f64()).unwrap_or(0.0), "location": n.fields.get("trips:location_name").and_then(|v| v["value"].as_str()).unwrap_or("")})).collect(); json_ok(serde_json::json!(map)) }
        _ => not_found()
    }
}
